import{_ as r,c as a,o,aj as t}from"./chunks/framework.C2N4vG9O.js";const p=JSON.parse('{"title":"核心组件导览","description":"Torch-RecHub 核心组件概述","frontmatter":{"title":"核心组件导览","description":"Torch-RecHub 核心组件概述"},"headers":[],"relativePath":"zh/core/intro.md","filePath":"zh/core/intro.md"}'),c={name:"zh/core/intro.md"};function d(h,e,i,n,l,s){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="核心组件导览" tabindex="-1">核心组件导览 <a class="header-anchor" href="#核心组件导览" aria-label="Permalink to “核心组件导览”">​</a></h1><p>以电影推荐为例。我们知道用户看过哪些电影，也知道这次给他展示了哪部电影。要训练一个预测点击的模型，需要先把这条记录变成模型能读的数字，再把预测结果和实际点击标签放在一起计算损失。</p><h2 id="一条记录怎样进入模型" tabindex="-1">一条记录怎样进入模型 <a class="header-anchor" href="#一条记录怎样进入模型" aria-label="Permalink to “一条记录怎样进入模型”">​</a></h2><ol><li><strong>编码。</strong> 假设词表里电影 <code>M42</code> 的编号是 <code>3</code>。用户只看过这部电影，历史长度设为 3，那么 <code>hist_movie_id</code> 就是 <code>[3, 0, 0]</code>。后两个位置是补齐用的。候选电影和历史电影要用同一份词表。<a href="/torch-rechub/zh/core/features.html">特征定义</a></li><li><strong>组批。</strong> 假设每批有 <code>B</code> 条记录，候选电影 ID 的形状是 <code>[B]</code>，历史是 <code>[B, 3]</code>。<code>DataGenerator</code> 把这些特征放在同一个字典里，连同 <code>B</code> 个点击标签交给训练器。<a href="/torch-rechub/zh/core/data.html">数据加载</a></li><li><strong>训练。</strong> 排序模型读取特征字典，给每条记录打分。<code>CTRTrainer.fit(train_dl, val_dl)</code> 用训练集更新参数，每轮在验证集上计算 AUC。<a href="/torch-rechub/zh/core/evaluation.html">训练与评估</a></li></ol><h2 id="其他任务用哪个训练器" tabindex="-1">其他任务用哪个训练器 <a class="header-anchor" href="#其他任务用哪个训练器" aria-label="Permalink to “其他任务用哪个训练器”">​</a></h2><p>召回时要从物品库中选出候选。<code>MatchDataGenerator</code> 为用户和物品分别准备数据，<code>MatchTrainer</code> 可以在双塔模型训练结束后分别算出两侧向量。<a href="/torch-rechub/zh/tutorials/retrieval.html">召回教程</a></p><p>一条样本有多个标签时，仍可用 <code>DataGenerator</code> 组批。按标签列的顺序配置 <code>MTLTrainer</code> 的任务，训练后可以单独查看每个任务的指标。<a href="/torch-rechub/zh/tutorials/pipeline.html">多任务教程</a></p><p>HSTU 和 HLLM 用 <code>SequenceDataGenerator</code> 和 <code>SeqTrainer</code> 学习下一件物品。RQ-VAE 学习物品的语义 ID，TIGER 再学习如何生成这些 ID，两者各有对应的训练脚本。<a href="/torch-rechub/zh/models/generative.html">生成式模型</a></p>',8)])])}const m=r(c,[["render",d]]);export{p as __pageData,m as default};
